import com.dtm.platform.validation.ContentDataValidator;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import com.nimbusds.jose.jwk.source.ImmutableSecret;import javax.crypto.spec.SecretKeySpec;import java.util.*;import java.time.*;
public class JavaSecuritySmoke {
 static void check(boolean pass,String message){if(!pass)throw new AssertionError(message);System.out.println("PASS "+message);}
 public static void main(String[] args){var passwords=new BCryptPasswordEncoder(12);String hash=passwords.encode("verification-password-only");check(!hash.contains("verification-password"),"password is hashed");check(passwords.matches("verification-password-only",hash),"password verifies");check(!passwords.matches("wrong",hash),"wrong password fails");byte[] random=new byte[48];new java.security.SecureRandom().nextBytes(random);var key=new SecretKeySpec(random,"HmacSHA256");var encoder=new NimbusJwtEncoder(new ImmutableSecret<>(key));var decoder=NimbusJwtDecoder.withSecretKey(key).macAlgorithm(MacAlgorithm.HS256).build();decoder.setJwtValidator(JwtValidators.createDefaultWithIssuer("dtm-platform"));var now=Instant.now();var token=encoder.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),JwtClaimsSet.builder().issuer("dtm-platform").subject("verification@example.test").issuedAt(now).expiresAt(now.plusSeconds(60)).claim("roles",List.of("EDITOR")).build())).getTokenValue();check(decoder.decode(token).getClaimAsStringList("roles").contains("EDITOR"),"JWT role and signature validate");try{decoder.decode(token.substring(0,token.lastIndexOf('.')+1)+"invalid");throw new AssertionError("Forged JWT accepted");}catch(JwtException expected){System.out.println("PASS forged JWT fails");}ContentDataValidator.validate("projects",Map.of("liveUrl","https://example.test"));try{ContentDataValidator.validate("projects",Map.of("liveUrl","javascript:alert(1)"));throw new AssertionError("Unsafe link accepted");}catch(IllegalArgumentException expected){System.out.println("PASS unsafe URL fails");}try{ContentDataValidator.validate("settings",Map.of("apiKey","secret"));throw new AssertionError("Secret accepted");}catch(IllegalArgumentException expected){System.out.println("PASS public secret fields fail");}}
}
